def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Phase 1: opening. Cooperate unless hit repeatedly.
    if n < 6:
        opp_d = sum(1 for m, o in history if o == 'D')
        if opp_d >= 3:
            return 'D'
        return 'C'

    opp_d_total = 0
    my_d_total = 0
    for m, o in history:
        if o == 'D':
            opp_d_total += 1
        if m == 'D':
            my_d_total += 1

    # Opponent appears to be unconditional cooperator: exploit but keep some goodwill.
    if opp_d_total == 0:
        if n >= 90:
            return 'D'
        if n > 20 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent almost always defects: defect, with rare probing cooperation.
    if opp_d_total * 100 >= n * 90:
        if n < 85 and rng.random() < 0.05:
            return 'C'
        return 'D'

    last_my, last_opp = history[-1]
    tail = history[-8:]
    opp_recent_d = sum(1 for m, o in tail if o == 'D')
    my_recent_d = sum(1 for m, o in tail if m == 'D')

    # Endgame: if opponent has been cooperative enough, defect to grab points.
    if n >= 94:
        if opp_d_total * 100 <= n * 35:
            return 'D'
        return 'C'

    # Strong recent defection: punish, but watch out for mutual defection traps.
    if opp_recent_d >= 5:
        if my_recent_d >= 5 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Three consecutive opponent defections: retaliate hard.
    if n >= 3 and history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
        return 'D'

    # Opponent just defected after cooperating: retaliate once.
    if last_opp == 'D':
        if last_my == 'C':
            return 'D'
        # We already defected; if opponent has mostly been cooperative, forgive.
        if opp_d_total * 100 <= n * 20:
            return 'C'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we just defected as punishment, return to cooperation.
    if last_my == 'D':
        return 'C'

    # Against mostly cooperative opponents: cooperate, occasionally exploit if far ahead.
    if opp_d_total * 100 <= n * 20:
        if n > 30 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderately defective opponent: mix, leaning cooperative to preserve mutual CC.
    if opp_d_total * 100 <= n * 45:
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    # Defection-heavy opponent: retaliate often but allow recovery.
    if rng.random() < 0.15:
        return 'C'
    return 'D'
